class EmilTraceLoggerParser(object):
    """
    This is main class of emil trace collector and parser
    """
    ROBOT_LIBRARY_SCOPE = 'TEST CASE'
    ROBOT_LISTENER_API_VERSION = 2
    messages_structures = {}
    bin_trace_file_store = {}
    # dict { 'alias': [ path_to_bin_file, 0/1 ] } 0/1 - indicates if tracing collection completed

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self

    @staticmethod
    def enable_pmi_ticket_collection(pmi_flag_id='0x00130041'):
        """
            Changes R&D parameter - pmiTictektsEnabled
            - online through AaShell to value TRUE
            :return: None
        """
        logger.debug('Changing {} to value 1'.format(pmi_flag_id))
        change_rad_param(param=pmi_flag_id, value='1', is_permanent=False)

    @staticmethod
    def disable_pmi_ticket_collection(pmi_flag_id='0x00130041'):
        """
            Changes R&D parameter - pmiTictektsEnabled
            - online through AaShell to value FALSE
            :return: None
        """
        logger.debug('Changing {} to value 0'.format(pmi_flag_id))
        change_rad_param(param=pmi_flag_id, value='0', is_permanent=False)

    @staticmethod
    def start_enb_tracing(msg_name=None, msg_hex=None, node_id=None, alias=None):
        """
            Start tracing procedure with requested filters, trace result is writen to file
            only after using of stop_cli_aatrace_tracing() method from this class
            :param alias      - alias used to create trace bin path, unique per test case
            :param msg_hex    - string with messages hex representation where ',' is separator
            :param msg_name   - string with messages name where ',' is separator
            :param node_id    - string with specific node_id where ',' is separator
            :return: None

            +---------------------------------------------------------------------------------+
            |  Examples                                                                       |
            +=================================================================================+
            | Start eNB Tracing                                                               |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_name=CELLC_CELL_RECONFIGURATION_REQ_MSG, UEC_PMI_TICKET_IND_MSG     |
            |                                                                                 |
            |  WHEN YOU USE HEX:                                                              |
            |                                                                                 |
            | Start eNB Tracing                                                               |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x426A-0x426B, 0x3308, 0x3422-0x3444, 0x2000                    |
            |                                                                                 |
            |  WHEN YOU USE NODE_ID:                                                          |
            |                                                                                 |
            | Start eNB Tracing                                                               |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x4e3a                                                          |
            |   ...   node_id=0x124a, 0x224a                                                  |
            +---------------------------------------------------------------------------------+
        """

        trace_output_dir = '/home/ute/enb_trace_testing/'
        trace_output_file = trace_output_dir + 'CLI_TRACE_{}.bin'.format(alias)
        logger.debug('Prepare to start cli_aatrace for enb with {} messages and output_file {}'.format(msg_name,
                                                                                                       trace_output_file))

        if EmilTraceLoggerParser.check_cli_aatrace_tracing_in_progress():
            raise TraceStartError()

        EmilTraceLoggerParser.prepare_sack_files()

        parsed_filters = TraceCollector.generate_cli_filters(msg_name, EmilTraceLoggerParser.messages_structures,
                                                             msg_hex)
        if node_id:
            aashell_data = TraceCollector.get_platform_info_from_aashell()
            node_ids = TraceCollector.parse_node_id_list(node_id)
            platform = TraceCollector.get_hw_platform_type(aashell_data)
        else:
            platform, node_ids = TraceCollector.get_hw_platform_and_core_ids_for_uec()

        cmd = TraceCollector.build_cli_aatrace_command(platform, node_ids, trace_output_file, parsed_filters)

        TraceCollector.check_required_os_resources(trace_output_dir, trace_output_file)
        EmilTraceLoggerParser._save_trace_alias(alias, trace_output_file)

        cli_process = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        logger.debug('cli_aatrace command: {} cli_aatrace pid {}'.format(cmd, cli_process.pid))

        return trace_output_file

    @staticmethod
    def start_bin_trace_collection(msg_hex=None, node_id=None, alias='DEFAULT',
                                   trace_output_file='CLI_TRACE_BIN_DEFAULT',
                                   trace_output_dir='/home/ute/enb_trace_testing'):
        """
            Start tracing procedure with requested filters, trace result is writen to file
            only after using of stop_cli_aatrace_tracing() method from this class
            :param alias      - alias used to create trace bin path, unique per test case
            :param msg_hex    - string with messages hex representation where ',' is separator
            :param node_id    - string with specific node_id where ',' is separator
            :param trace_output_file - filename for collected BIN
            :param trace_output_dir - directory where to save collected trace BIN file
            :return: None

            +---------------------------------------------------------------------------------+
            |  Examples                                                                       |
            +=================================================================================+
            |                                                                                 |
            |  WHEN YOU USE HEX AND TRACE FOR UEC:                                            |
            |                                                                                 |
            | Start BIN Trace Collection                                                      |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x426A-0x426B, 0x3308, 0x3422-0x3444, 0x2000                    |
            |                                                                                 |
            |  WHEN YOU USE NODE_ID:                                                          |
            |                                                                                 |
            | Start BIN Trace Collection                                                      |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x4e3a                                                          |
            |   ...   node_id=0x124a, 0x224a                                                  |
            +---------------------------------------------------------------------------------+
        """
        if EmilTraceLoggerParser.check_cli_aatrace_tracing_in_progress():
            raise TraceStartError()

        trace_file = BinTraceCollector.bin_trace_start(msg_hex, node_id, alias, trace_output_file, trace_output_dir)

        EmilTraceLoggerParser._save_trace_alias(alias=alias, trace_output_file=trace_file)

        return trace_file

    @staticmethod
    def check_cli_aatrace_tracing_in_progress():
        """
            Check if tracing procedure with cli_aatrace is running
            Check is based on connection to trace server on port 15004

            :return: False/True
        """
        return bool('ESTABLISHED' in TraceCollector.get_cli_aatrace_process())

    @staticmethod
    def stop_enb_tracing(alias):
        """
            Kill cli_aatrace tracing process when exists. After sending kill -2 traces
            are saved to output_file proper for started alias
            :param alias      - alias of enb tracing that was started with start_enb_tracing()
            :return: None


            +---------------------------------------------------------------------------------+
            |  Examples                                                                       |
            +=================================================================================+
            | Stop eNB Tracing                                                                |
            |   ...   alias=enb_trace_1                                                       |
            +---------------------------------------------------------------------------------+
        """
        if EmilTraceLoggerParser.check_cli_aatrace_tracing_in_progress():
            cmd = 'ps -ef | awk \'/[c]li_aatrace_utility_debian/{print $2}\' | xargs kill -2 '
            subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=True)
            logger.debug('Close cli_aatrace process')
        sleep(3)
        if EmilTraceLoggerParser.check_cli_aatrace_tracing_in_progress():
            raise TraceStopError()
        else:
            logger.debug('Set trace collecting for alias: {} from bin_trace_file_store as completed'.format(alias))
            try:
                EmilTraceLoggerParser.bin_trace_file_store[alias][1] = 1
            except:
                raise TraceStopAliasError(alias, list(EmilTraceLoggerParser.bin_trace_file_store.keys()))

    @staticmethod
    def stop_bin_trace_collection(alias):
        """
            Kill cli_aatrace tracing process when exists. After sending kill -2 traces
            are saved to output_file proper for started alias
            :param alias      - alias of enb tracing that was started with start_bin_trace_collection
            :return: None


            +---------------------------------------------------------------------------------+
            |  Examples                                                                       |
            +=================================================================================+
            | Stop BIN Trace Collection                                                       |
            |   ...   alias=enb_trace_1                                                       |
            +---------------------------------------------------------------------------------+
        """
        EmilTraceLoggerParser.stop_enb_tracing(alias)

    @staticmethod
    def verify_message_with_occurrence_number_has_field_eq(msg_name, alias,
                                                           field_name, hex_value, occurrence_number):
        """
            Check that emil_message_with occurrence number has filed name eq to given hex value.

            :param msg_name: string - EMIL msg name
            :param alias: string - path  - alias used to create trace bin path
            :param field_name: string - msg field name which will be verifying
            :param hex_value: string - expected hex value
            :param occurrence_number integer - in which msg expected msg should occurred
            :return: None

            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            | verify_message_with_occurrence_number_has_field_eq    |
            |   ...   alias=trace_enb1                              |
            |   ...   field_name=event                              |
            |   ...   hex_value=0F                                  |
            |   ...   occurrence_number=6                           |
            +-------------------------------------------------------+
        """
        occurrence_number = int(occurrence_number)
        messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                   msg_name)
        message = EmilTraceLoggerParser._get_message_by_occurrence_number(messages_with_the_same_hex_id,
                                                                          occurrence_number)
        field_value = EmilTraceLoggerParser._get_field_from_message(message, field_name)

        assert (field_value == hex_value.lower()), (
            "msg {} has not field {} eq to {} |||| actual_value: {}".format(
                msg_name, field_name, hex_value, field_value
            ))

    @staticmethod
    def verify_number_of_occurrences_of_given_message_with_field_eq_to_given_value(
            msg_name, alias, field_name, hex_value, number_of_occurrences):

        """
            Check that emil_msg occurred given number of times with filed eq to given hex value.

            :param msg_name: string - EMIL msg name
            :param alias: string - path  - alias used to create trace bin path
            :param field_name: string - msg field name which will be verifying
            :param hex_value: string - expected hex value
            :param number_of_occurrences integer - how many msgs with field eq to given value should be in given trace
            :return: None

            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            | verify_message_with_occurrence_number_has_field_eq    |
            |   ...   alias=trace_enb1                              |
            |   ...   msg_name=TUP_SRB_SEND_REQ_MSG                 |
            |   ...   field_name=HarqRespFlag                       |
            |   ...   hex_value=00000001                            |
            |   ...   number_of_occurrences=6                       |
            +-------------------------------------------------------+
        """
        given_number_of_occurrences = int(number_of_occurrences)
        number_of_occurrences = EmilTraceLoggerParser.get_number_of_messages_with_field_eq_to_given_value(
            alias, msg_name, field_name, hex_value)

        assert (given_number_of_occurrences == number_of_occurrences), (
            "In trace msg {msg_name} with field {field_name} eq to {hex_value} occurred {number_of_occurrences} times "
            "|||| not expected {given_num_of_occuences} times".format(
                msg_name=msg_name, field_name=field_name, hex_value=hex_value,
                number_of_occurrences=number_of_occurrences, given_num_of_occuences=given_number_of_occurrences))

    @staticmethod
    def verify_message_with_occurrence_number_does_not_have_field_eq(msg_name, alias,
                                                                     field_name, hex_value,
                                                                     occurrence_number):
        """
            Check that emil_message_with occurrence number does not have filed name eq to given hex value.

            :param msg_name: string - EMIL msg name
            :param alias: string - path  - alias used to create trace bin path
            :param field_name: string - msg field name which will be verifying
            :param hex_value: string - expected hex value
            :param occurrence_number integer - in which msg expected msg should occurred
            :return: None

            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            | verify_message_with_occurrence_number_has_field_eq    |
            |   ...   hex_id=UEC_PMI_TICKET_IND_MSG                 |
            |   ...   alias=trace_enb1                              |
            |   ...   field_name=event                              |
            |   ...   hex_value=0f                                  |
            |   ...   occurrence_number=6                           |
            +-------------------------------------------------------+
        """
        occurrence_number = int(occurrence_number) - 1
        messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                   msg_name)
        message = EmilTraceLoggerParser._get_message_by_occurrence_number(messages_with_the_same_hex_id,
                                                                          occurrence_number)
        field_value = EmilTraceLoggerParser._get_field_from_message(message, field_name)

        assert (field_value != hex_value), (
            "msg {} has field {} eq to {} |||| but expected {}".format(
                msg_name, field_name, hex_value, field_value
            ))

    @staticmethod
    def verify_message_occurs_given_number_of_times(msg_name, number_of_occurrences,
                                                    alias):
        """
            Check that emil_message has msg with hex_id given number of occurrences.

            :param msg_name: string - EMIL msg name
            :param alias: string - path  - alias used to create trace bin path
            :param number_of_occurrences integer - how many msg with hex_id is expected
            :return: None

            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            | verify_message_with_occurrence_number_has_field_eq    |
            |   ...   hex_id=UEC_PMI_TICKET_IND_MSG                 |
            |   ...   alias=traceenb1                               |
            |   ...   occurrence_number=6                           |
            +-------------------------------------------------------+
        """
        number_of_occurrences = int(number_of_occurrences)
        messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                   msg_name)
        assert (len(messages_with_the_same_hex_id) == number_of_occurrences), (
            "msg {} did not occure {} times, but occured {} times".format(
                msg_name, number_of_occurrences, len(messages_with_the_same_hex_id)
            ))

    @staticmethod
    def verify_message_did_not_occurred_in_trace(msg_name, alias):
        """
            Check that emil_message did not occured in trace.

            :param msg_name: string - EMIL msg name
            :param alias: string - path  - alias used to create trace bin path
            :return: None

            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            |  verify_message_did_not_occurred_in_trace             |
            |   ...   hex_id=UEC_PMI_TICKET_IND_MSG                 |
            |   ...   alias=traceenb1                               |
            +-------------------------------------------------------+
        """
        messages_with_the_same_hex_id = None
        try:
            messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                       msg_name)
        except MsgDoesNotExistInTrace:
            print("Msg Does Not Exist Like ")

        if messages_with_the_same_hex_id:
            raise UnexpectedMsgOccurred("Msg {} occurred but not expected".format(msg_name))

    @staticmethod
    def verify_trace_bin_file_is_empty(alias):
        """
            Check that collected trace bin file is empty
            :param alias: string - path  - alias used to create trace bin path
            :return:
            +-------------------------------------------------------+
            |  Examples                                             |
            +=======================================================+
            | verify_trace_bin_file_is_empty                        |
            |   ...   alias=traceenb1                               |
            +-------------------------------------------------------+
        """
        emil_trace_bin_file = EmilTraceLoggerParser.bin_trace_file_store[alias][0]
        file_size = os.stat(emil_trace_bin_file).st_size
        # with codecs.open(emil_trace_bin_file) as trace_file:
        #     trace = trace_file.read()
        assert file_size == 0, 'Trace file is not empty!!!  file size: {}'.format(file_size)

    @staticmethod
    def get_field_from_msg(alias, msg_name, occurrence_number, field_name):
        """

        :param alias:
        :param msg_name:
        :param occurrence_number:
        :param field_name:
        :return: field value for given msg
        +-------------------------------------------------------+
        |  Examples                                             |
        +=======================================================+
        | get_field_from_msg                                    |
        |   ...   alias=trace_enb1                              |
        |   ...   msg_name=TUP_SRB_SEND_REQ_MSG                 |
        |   ...   field_name=HarqRespFlag                       |
        |   ...   occurrence_number=1                           |
        +-------------------------------------------------------+
        """

        occurrence_number = int(occurrence_number) - 1
        messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                   msg_name)
        message = EmilTraceLoggerParser._get_message_by_occurrence_number(messages_with_the_same_hex_id,
                                                                          occurrence_number)
        field_value = EmilTraceLoggerParser._get_field_from_message(message, field_name)

        return field_value

    @staticmethod
    def get_number_of_messages_with_field_eq_to_given_value(alias, msg_name, field_name, field_hex_value):
        """

        :param alias:
        :param msg_name:
        :param field_name:
        :param field_hex_value:
        :return:
        """
        messages_with_the_same_hex_id = EmilTraceLoggerParser.get_single_type_parsed_emil_messages(alias,
                                                                                                   msg_name)
        number_of_occurrences = 0
        for message in messages_with_the_same_hex_id:
            if EmilTraceLoggerParser._get_field_from_message(message, field_name) == field_hex_value.lower():
                number_of_occurrences += 1
        return number_of_occurrences

    @staticmethod
    def _get_field_from_message(message, field_name):
        """
        :param message:
        :param field_name:
        :return:
        """
        field_name = field_name.lower()
        if field_name not in message:
            raise MsgDoesNotContainField("Msg: {} does not have field: {}".format(message, field_name))
        else:
            field = message[field_name]
        return field.replace("'", "")

    @staticmethod
    def _get_message_by_occurrence_number(msg_grouped_by_hex, occurrence_num):
        """
        :param msg_grouped_by_hex:
        :param occurrence_num:
        :return:
        """
        occurrence_num_index = occurrence_num - 1
        if occurrence_num_index > len(msg_grouped_by_hex) - 1:
            raise MsgDoesNotOccuredGivenNumberOfTimes(
                "Msg does not occurred given number of times: {}, but occured: {} times".format(
                    occurrence_num, len(msg_grouped_by_hex)))
        else:
            msg = msg_grouped_by_hex[occurrence_num_index]
        return msg

    @staticmethod
    def _get_messages_by_hex_from_parsed_emil_messages(parsed_msg, hex_id):
        """
        :param parsed_msg:
        :param hex_id:
        :return:
        """
        try:
            msg = parsed_msg[hex_id]
        except KeyError:
            logger.console("Msg: {} does not exist in trace".format(hex_id))
            raise
        return msg

    @staticmethod
    def get_all_parsed_emil_messages(alias):
        """
        :param alias:
        :return:
        """
        return EmilMessagesParser(EmilTraceLoggerParser.get_unparsed_emil_messages(
               alias)).get_all_parsed_messages(EmilTraceLoggerParser.messages_structures)

    @staticmethod
    def save_all_parsed_emil_messages_to_file(alias, path_to_file_destination):
        """
           Save all parsed messages to file.

            :param alias: string - path  - alias used to create trace bin path
            :param path_to_file_destination integer - how many msg with hex_id is expected
            :return: None

            +-------------------------------------------------------------------+
            |  Examples                                                         |
            +===================================================================+
            | verify_message_with_occurrence_number_has_field_eq                |
            |   ...   alias=traceenb1                                           |
            |   ...   ath_to_file_destination=/home/ute/parsed_emil_msgs.txt    |
            +-------------------------------------------------------------------+
        """
        parsed_msgs = EmilTraceLoggerParser.get_all_parsed_emil_messages(alias)
        with codecs.open(path_to_file_destination, 'w+') as txt_file:
            txt_file.write(json.dumps(parsed_msgs))

    @staticmethod
    def get_single_type_parsed_emil_messages(alias, msg_name):
        """

        :param alias: string - path  - alias used to create trace bin path
        :param msg_name:
        :return:
        """
        msg_hex_id = EmilTraceLoggerParser.get_message_hex_id_by_name(msg_name)
        return EmilMessagesParser(EmilTraceLoggerParser.get_unparsed_emil_messages(
               alias)).get_single_type_parsed_messages(msg_hex_id,
                                                       EmilTraceLoggerParser.messages_structures)

    @staticmethod
    def get_message_hex_id_by_name(msg_name):
        """

        :param msg_name:
        :return:
        """
        if not EmilTraceLoggerParser.messages_structures:
            raise SackFileNotLoadedToParser('SACK file not loaded to parser! Check if you used proper tracing method !')
        elif msg_name in EmilTraceLoggerParser.messages_structures:
            return EmilTraceLoggerParser.messages_structures[msg_name]['hex_id']
        else:
            raise MsgDoesNotExistInSacksFile('Msg {} doest not exist in sack codec file for current enb_sw_build'.format(
                                             msg_name))

    @staticmethod
    def get_unparsed_emil_messages(alias):
        """

        :param alias: string - path  - alias used to create trace bin path
        :return:
        """
        emil_trace_bin_file = EmilTraceLoggerParser.bin_trace_file_store[alias][0]
        emil_message_reader = EmilMessagesReader(emil_trace_bin_file)
        return emil_message_reader.unparsed_messages()

    @staticmethod
    def prepare_sack_files():
        """

        :return:
        """
        if EmilTraceLoggerParser.messages_structures:
            pass
        else:
            sack_downloader_p = SackDownloader()
            types_dat_file = sack_downloader_p.get_types_dat_file()
            EmilTraceLoggerParser.messages_structures = MessageStructureDecoder.get_structures_for_all_messages(
                types_dat_file)

    @staticmethod
    def _save_trace_alias(alias, trace_output_file):
        if alias in EmilTraceLoggerParser.bin_trace_file_store:
            raise TraceStartAliasError(alias, list(EmilTraceLoggerParser.bin_trace_file_store.keys()))
        else:
            logger.debug('Adding alias: {} with file path: {} to bin_trace_file_store that already contains: {}'.format(
                alias, trace_output_file, EmilTraceLoggerParser.bin_trace_file_store))
            EmilTraceLoggerParser.bin_trace_file_store[alias] = [trace_output_file, 0]

    @staticmethod
    def _cleanup_after_tracing_process():
        """
        Stops following tracing operations used aliases
        If using ROBOT FRAMEWORK it is not mandatory to call this method
        as it will be called automaticaly at the end of test suite.
        If used from Python it is needed to call this method to allow threads to safely end.

        :returns: None.
        """
        EmilTraceLoggerParser.bin_trace_file_store = {}
        EmilTraceLoggerParser.messages_structures = {}

    def _end_test(self, name, attr):
        logger.debug('Cleaning library scope from stored tracing '
                     'aliases: {}'.format(list(EmilTraceLoggerParser.bin_trace_file_store.keys())))
        EmilTraceLoggerParser._cleanup_after_tracing_process()


class MsgDoesNotOccuredGivenNumberOfTimes(Exception):
    """
    Exception MsgDoesNotOccuredGivenNumberOfTimes
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)


class MsgDoesNotContainField(Exception):
    """
    Exception MsgDoesNotContainField
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)


class MsgDoesNotExistInSacksFile(Exception):
    """
    Exception MsgDoesNotExistInSacksFile
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)


class UnexpectedMsgOccurred(Exception):
    """
    Exception UnexpectedMsgOccurred
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)
